#include <algorithm>
#include <cstdint>
#include <string>

using NTSTATUS = std::int32_t;
constexpr NTSTATUS STATUS_SUCCESS = 0;
constexpr NTSTATUS STATUS_BUFFER_TOO_SMALL = static_cast<NTSTATUS>(0xC0000023u);
struct UNICODE_STRING { std::uint16_t Length; std::uint16_t MaximumLength; char16_t* Buffer; };

namespace
{
    char16_t fold(char16_t c) { return c >= u'a' && c <= u'z' ? static_cast<char16_t>(c - u'a' + u'A') : c; }
    std::size_t chars(const UNICODE_STRING& s) { return s.Length / sizeof(char16_t); }
}

void initString(UNICODE_STRING& s, const char16_t* text)
{
    if (!text) { s = { 0, 0, nullptr }; return; }
    std::size_t n{ 0 };
    while (text[n]) ++n;
    s.Buffer = const_cast<char16_t*>(text);
    s.Length = static_cast<std::uint16_t>(n * sizeof(char16_t));
    s.MaximumLength = static_cast<std::uint16_t>(s.Length + sizeof(char16_t));
}

void copyString(UNICODE_STRING& dest, const UNICODE_STRING& src)
{
    const std::size_t room{ dest.MaximumLength / sizeof(char16_t) };
    const std::size_t n{ std::min(chars(src), room) };
    for (std::size_t i{ 0 }; i < n; ++i) dest.Buffer[i] = src.Buffer[i];
    dest.Length = static_cast<std::uint16_t>(n * sizeof(char16_t));
    if (n < room) dest.Buffer[n] = u'\0';
}

NTSTATUS appendString(UNICODE_STRING& dest, const UNICODE_STRING& src)
{
    if (static_cast<std::size_t>(dest.Length) + src.Length > dest.MaximumLength) return STATUS_BUFFER_TOO_SMALL;
    const std::size_t at{ chars(dest) };
    for (std::size_t i{ 0 }; i < chars(src); ++i) dest.Buffer[at + i] = src.Buffer[i];
    dest.Length = static_cast<std::uint16_t>(dest.Length + src.Length);
    if (dest.Length + sizeof(char16_t) <= dest.MaximumLength) dest.Buffer[chars(dest)] = u'\0';
    return STATUS_SUCCESS;
}

bool isPrefix(const UNICODE_STRING& prefix, const UNICODE_STRING& s, bool ignoreCase)
{
    if (prefix.Length > s.Length) return false;
    for (std::size_t i{ 0 }; i < chars(prefix); ++i)
    {
        const char16_t a{ prefix.Buffer[i] }, b{ s.Buffer[i] };
        if (ignoreCase ? fold(a) != fold(b) : a != b) return false;
    }
    return true;
}

bool equalStrings(const UNICODE_STRING& a, const UNICODE_STRING& b, bool ignoreCase)
{
    return a.Length == b.Length && isPrefix(a, b, ignoreCase);
}

std::u16string toStd(const UNICODE_STRING& s)
{
    return s.Buffer ? std::u16string(s.Buffer, chars(s)) : std::u16string();
}

unitTests:
TEST("init") {
    UNICODE_STRING s{}; initString(s, u"\\Device\\XenonEcho"); CHECK_EQ(int(s.Length), 34); CHECK_EQ(int(s.MaximumLength), 36);
    initString(s, nullptr); CHECK_EQ(int(s.Length), 0); CHECK(s.Buffer == nullptr);
}
TEST("lengths, not nulls") {
    char16_t raw[]{ u'a', u'b', u'c', u'X', u'Y' }; UNICODE_STRING s{ 6, 10, raw };
    CHECK(toStd(s) == u"abc");
}
TEST("copy into a small buffer") {
    UNICODE_STRING src{}; initString(src, u"Granite");
    char16_t small[4]{ u'?', u'?', u'?', u'?' }; UNICODE_STRING dest{ 0, 8, small };
    copyString(dest, src); CHECK_EQ(int(dest.Length), 8); CHECK(toStd(dest) == u"Gran");
    char16_t big[10]{}; UNICODE_STRING d2{ 0, 20, big }; copyString(d2, src); CHECK_EQ(int(d2.Length), 14); CHECK(big[7] == u'\0');
}
TEST("append") {
    char16_t buf[12]{}; UNICODE_STRING d{ 0, 24, buf }; UNICODE_STRING a{}, b{}; initString(a, u"\\??\\"); initString(b, u"XenonEcho");
    CHECK_EQ(appendString(d, a), STATUS_SUCCESS); CHECK_EQ(appendString(d, b), STATUS_BUFFER_TOO_SMALL); CHECK(toStd(d) == u"\\??\\");
    UNICODE_STRING c{}; initString(c, u"Xenon"); CHECK_EQ(appendString(d, c), STATUS_SUCCESS); CHECK(toStd(d) == u"\\??\\Xenon"); CHECK_EQ(int(d.Length), 18);
}
TEST("compare and prefix") {
    UNICODE_STRING a{}, b{}, p{}; initString(a, u"\\Device\\XenonEcho"); initString(b, u"\\DEVICE\\xenonecho"); initString(p, u"\\device\\");
    CHECK(equalStrings(a, b, true)); CHECK(!equalStrings(a, b, false)); CHECK(isPrefix(p, a, true)); CHECK(!isPrefix(p, a, false)); CHECK(!isPrefix(a, p, true));
}

